"""Output writers.

Values that json can't serialize natively (Decimal, date) are rendered
as strings, matching the storefront convention of JSON-safe payloads.
"""

import csv
import datetime
import json
import os
from decimal import Decimal

from ..errors import LoadError


def _jsonable(value):
    if isinstance(value, Decimal):
        return str(value)
    if isinstance(value, (datetime.date, datetime.datetime)):
        return value.isoformat()
    return value


def _clean(record):
    """Drop bookkeeping keys and coerce values for output."""
    return {
        key: _jsonable(value)
        for key, value in record.items()
        if not key.startswith("_")
    }


def _ensure_parent(path):
    parent = os.path.dirname(path)
    if parent:
        os.makedirs(parent, exist_ok=True)


def write_records(path, fmt, records):
    """Write records to `path` in `fmt`; returns the number written."""
    _ensure_parent(path)
    if fmt == "jsonl":
        return _write_jsonl(path, records)
    if fmt == "csv":
        return _write_csv(path, records)
    raise LoadError("no writer for format %r" % fmt)


def _write_jsonl(path, records):
    try:
        with open(path, "w", encoding="utf-8") as fh:
            for record in records:
                fh.write(json.dumps(_clean(record), sort_keys=True) + "\n")
    except OSError as exc:
        raise LoadError("could not write %s: %s" % (path, exc))
    return len(records)


def _write_csv(path, records):
    if not records:
        # still create the file so downstream jobs see an empty target
        _ensure_parent(path)
        open(path, "w", encoding="utf-8").close()
        return 0
    fieldnames = sorted({key for r in records for key in _clean(r)})
    try:
        with open(path, "w", encoding="utf-8", newline="") as fh:
            writer = csv.DictWriter(fh, fieldnames=fieldnames)
            writer.writeheader()
            for record in records:
                writer.writerow({k: _jsonable(v) for k, v in _clean(record).items()})
    except (OSError, csv.Error) as exc:
        raise LoadError("could not write %s: %s" % (path, exc))
    return len(records)


def write_rejects(path, rejects):
    """Write reject entries as JSONL; returns the number written."""
    _ensure_parent(path)
    try:
        with open(path, "w", encoding="utf-8") as fh:
            for entry in rejects:
                row = dict(entry)
                row["record"] = _clean(row.get("record", {}))
                fh.write(json.dumps(row, sort_keys=True, default=str) + "\n")
    except OSError as exc:
        raise LoadError("could not write rejects %s: %s" % (path, exc))
    return len(rejects)

"""Input readers.

Both readers return a list of dicts with string keys. CSV headers are
normalized to snake_case on the way in (see utils.text.normalize_header)
so specs can always refer to fields in one canonical spelling.
"""

import csv
import json
import os

from ..errors import ExtractError
from ..utils.text import normalize_header


def read_records(path, fmt):
    """Dispatch to the reader for `fmt`."""
    if not os.path.exists(path):
        raise ExtractError("source file not found: %s" % path)
    if fmt == "csv":
        return read_csv(path)
    if fmt == "jsonl":
        return read_jsonl(path)
    raise ExtractError("no reader for format %r" % fmt)


def read_csv(path):
    """Read a CSV file into a list of dicts, normalizing headers."""
    try:
        with open(path, "r", encoding="utf-8-sig", newline="") as fh:
            reader = csv.reader(fh)
            rows = list(reader)
    except (OSError, csv.Error) as exc:
        raise ExtractError("could not read CSV %s: %s" % (path, exc))

    if not rows:
        raise ExtractError("CSV %s is empty (no header row)" % path)

    header = [normalize_header(h) for h in rows[0]]
    seen = set()
    for name in header:
        if not name:
            raise ExtractError("CSV %s has a blank column header" % path)
        if name in seen:
            raise ExtractError(
                "CSV %s has duplicate column %r after normalization" % (path, name)
            )
        seen.add(name)

    records = []
    for lineno, row in enumerate(rows[1:], start=2):
        if not any(cell.strip() for cell in row):
            continue  # skip fully blank lines
        if len(row) != len(header):
            raise ExtractError(
                "CSV %s line %d has %d cells, expected %d"
                % (path, lineno, len(row), len(header))
            )
        record = dict(zip(header, (cell.strip() for cell in row)))
        record["_line"] = lineno
        records.append(record)
    return records


def read_jsonl(path):
    """Read a JSON-lines file into a list of dicts."""
    records = []
    try:
        with open(path, "r", encoding="utf-8") as fh:
            for lineno, line in enumerate(fh, start=1):
                line = line.strip()
                if not line:
                    continue
                try:
                    obj = json.loads(line)
                except json.JSONDecodeError as exc:
                    raise ExtractError(
                        "JSONL %s line %d is not valid JSON: %s" % (path, lineno, exc)
                    )
                if not isinstance(obj, dict):
                    raise ExtractError(
                        "JSONL %s line %d is not an object" % (path, lineno)
                    )
                obj["_line"] = lineno
                records.append(obj)
    except OSError as exc:
        raise ExtractError("could not read JSONL %s: %s" % (path, exc))
    return records

